/// Calculate the nth Fibonacci number using recursion.
/// 
/// # Examples
/// 
/// ```
/// use your_crate_name::fibonacci;
/// 
/// assert_eq!(fibonacci(0), 0);
/// assert_eq!(fibonacci(1), 1);
/// assert_eq!(fibonacci(10), 55);
/// ```
/// 
/// # Panics
/// 
/// Panics if n is greater than 93, as the result would overflow a u64.
pub fn fibonacci(n: u32) -> u64 {
    if n > 93 {
        panic!("fibonacci({}) would overflow u64", n);
    }

    match n {
        0 => 0,
        1 => 1,
        _ => fibonacci(n - 1) + fibonacci(n - 2),
    }
}

/// Calculate the nth Fibonacci number using memoized recursion.
/// More efficient than the naive recursive approach for larger n.
pub fn fibonacci_memoized(n: u32) -> u64 {
    if n > 93 {
        panic!("fibonacci({}) would overflow u64", n);
    }

    fn helper(n: u32, memo: &mut [Option<u64>]) -> u64 {
        if let Some(result) = memo[n as usize] {
            return result;
        }

        let result = match n {
            0 => 0,
            1 => 1,
            _ => helper(n - 1, memo) + helper(n - 2, memo),
        };

        memo[n as usize] = Some(result);
        result
    }

    let mut memo = vec![None; (n + 1) as usize];
    helper(n, &mut memo)
}

