use std::fs;
use std::path::{Path, PathBuf};
use thiserror::Error;

/// Errors that can occur when loading the API key
#[derive(Error, Debug)]
pub enum ApiKeyError {
    #[error("Failed to read API key file: {0}")]
    ReadError(#[from] std::io::Error),

    #[error("API key file not found at: {0}")]
    NotFound(PathBuf),

    #[error("API key is empty or contains only whitespace")]
    EmptyKey,

    #[error("API key contains invalid characters")]
    InvalidCharacters,
}

/// Secure API key container that prevents accidental logging
#[derive(Clone)]
pub struct ApiKey {
    key: String,
}

impl ApiKey {
    /// Minimum key length for security
    const MIN_LENGTH: usize = 16;

    /// Creates a new ApiKey from a string (for testing)
    pub fn new(key: String) -> Result<Self, ApiKeyError> {
        Self::validate(&key)?;
        Ok(Self { key })
    }

    /// Loads API key from the default location: secrets/api.key
    pub fn from_default_location() -> Result<Self, ApiKeyError> {
        Self::from_file("secrets/api.key")
    }

    /// Loads API key from a specific file path
    pub fn from_file<P: AsRef<Path>>(path: P) -> Result<Self, ApiKeyError> {
        let path = path.as_ref();

        if !path.exists() {
            return Err(ApiKeyError::NotFound(path.to_path_buf()));
        }

        let content = fs::read_to_string(path)?;
        Self::parse_key(&content)
    }

    /// Parses key content, stripping comments and whitespace
    fn parse_key(content: &str) -> Result<Self, ApiKeyError> {
        // Extract first non-comment, non-empty line
        let key = content
            .lines()
            .map(str::trim)
            .find(|line| !line.is_empty() && !line.starts_with('#'))
            .ok_or(ApiKeyError::EmptyKey)?;

        Self::validate(key)?;
        Ok(Self { key: key.to_string() })
    }

    /// Validates the key format
    fn validate(key: &str) -> Result<(), ApiKeyError> {
        if key.len() < Self::MIN_LENGTH {
            return Err(ApiKeyError::EmptyKey);
        }

        // Check for control characters (except common whitespace)
        if key.chars().any(|c| c.is_control() && !c.is_ascii_whitespace()) {
            return Err(ApiKeyError::InvalidCharacters);
        }

        Ok(())
    }

    /// Returns key as string slice for use in headers/requests
    /// 
    /// # Security
    /// Avoid logging or displaying this value
    pub fn as_str(&self) -> &str {
        &self.key
    }

    /// Returns key for use in Bearer token authorization header
    pub fn as_bearer_token(&self) -> String {
        format!("Bearer {}", self.key)
    }
}

// Prevent accidental printing of the key
impl std::fmt::Debug for ApiKey {
    fn fmt(&self, f: &mut std::fmt::Formatter<'_>) -> std::fmt::Result {
        f.debug_struct("ApiKey")
            .field("key", &"[REDACTED]")
            .finish()
    }
}

impl std::fmt::Display for ApiKey {
    fn fmt(&self, f: &mut std::fmt::Formatter<'_>) -> std::fmt::Result {
        write!(f, "[REDACTED]")
    }
}

/// Zeroize on drop for memory security (optional, requires zeroize crate)
#[cfg(feature = "secure")]
impl Drop for ApiKey {
    fn drop(&mut self) {
        use zeroize::Zeroize;
        self.key.zeroize();
    }
}

